// ==================== HELPER FUNCTIONS ====================

/**
 * Generate keyword string for a given type and subtype
 * @param {string} type - 'categories' or 'pages'
 * @param {string|null} subtype - specific category or page
 * @returns {string} Comma-separated keyword string
 */
export function generateKeywords(type, subtype = null) {
  const global = SEO_KEYWORDS.global;

  // If subtype is provided, try to find it
  if (subtype && SEO_KEYWORDS[type]?.[subtype]) {
    return [...global, ...SEO_KEYWORDS[type][subtype]].join(', ');
  }

  // If type itself is an array (for pages)
  if (SEO_KEYWORDS[type]) {
    if (Array.isArray(SEO_KEYWORDS[type])) {
      return [...global, ...SEO_KEYWORDS[type]].join(', ');
    }
  }

  // Fallback to global keywords
  return global.join(', ');
}

/**
 * Generate keywords for a game based on its properties
 * @param {Object} game - Game object with title, category, tagList
 * @returns {string} Comma-separated keyword string
 */
export function generateGameKeywords(game) {
  const keywords = new Set(SEO_KEYWORDS.global);

  // Add game title
  if (game.title) {
    keywords.add(game.title.toLowerCase());
    keywords.add(`play ${game.title.toLowerCase()}`);
    keywords.add(`${game.title.toLowerCase()} online`);
  }

  // Add category keywords
  if (game.category) {
    const categoryKey = game.category.toLowerCase();
    const categoryKeywords = SEO_KEYWORDS.categories[categoryKey];
    if (categoryKeywords) {
      categoryKeywords.forEach(kw => keywords.add(kw));
    } else {
      keywords.add(`${categoryKey} games`);
      keywords.add(`free ${categoryKey} games`);
    }
  }

  // Add tag-based keywords
  if (game.tagList && Array.isArray(game.tagList)) {
    game.tagList.forEach(tag => {
      const tagKey = tag.toLowerCase();
      const tagKeywords = SEO_KEYWORDS.categories[tagKey];
      if (tagKeywords) {
        // Add first 3 keywords from each tag
        tagKeywords.slice(0, 3).forEach(kw => keywords.add(kw));
      } else {
        keywords.add(`${tagKey} games`);
      }
    });
  }

  return Array.from(keywords).join(', ');
}

/**
 * Get category display name
 * @param {string} categoryId - Category identifier
 * @returns {string} Human-readable category name
 */
export function getCategoryDisplayName(categoryId) {
  const names = {
    'endless runner': 'Endless Runner',
    'girls games': 'Girls Games',
    'tower_defense': 'Tower Defense',
    'hyper_casual': 'Hyper Casual',
    // Add more custom mappings as needed
  };

  return names[categoryId] || categoryId
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

/**
 * Get related categories for a given category
 * @param {string} categoryId - Category identifier
 * @returns {Array} Array of related category IDs
 */
export function getRelatedCategories(categoryId) {
  const relations = {
    shooting: ['action', 'war', 'fps', 'gun'],
    driving: ['racing', 'cars', 'simulation'],
    racing: ['driving', 'cars', 'sports'],
    action: ['shooting', 'fighting', 'war', 'adventure'],
    horror: ['halloween', 'scary', 'zombie'],
    puzzle: ['logic', 'strategy', 'memory'],
    kids: ['girls games', 'fun', 'educational', 'casual'],
    arcade: ['fun', 'classic', 'casual', 'retro'],
    platformer: ['endless runner', 'skill', 'adventure'],
    sports: ['basketball', 'football', 'racing'],
    simulation: ['driving', 'strategy', 'simulator'],
    card: ['puzzle', 'strategy', 'casual'],
    // Add more relations as needed
  };

  return relations[categoryId] || [];
}